INSERT INTO "complaints" ("id", "ticket_number", "name", "email", "phone", "category", "subject", "message", "attachment_path", "is_anonymous", "status", "response", "responded_at", "ip_address", "created_at", "updated_at", "student_id", "faculty") VALUES (1, 'DPM-261029-7A8B', 'Fathurrahman Al-Ghifari', '21522045@students.uii.ac.id', 081234567890, 'Fasilitas & Sarana Prasarana', 'Permohonan Penambahan Stopkontak dan Penguatan Wifi Gedung FTI', 'Mohon kepada DPM UII untuk mengadvokasikan penambahan fasilitas stopkontak di selasar lantai 2 dan 3 Gedung Mas Mansyur FTI serta optimalisasi jaringan wifi edukasi yang sering mengalami lonjakan trafik pada jam kuliah sibuk.', NULL, FALSE, 'baru', NULL, NULL, NULL, '2026-10-30 10:58:53', '2026-10-30 12:58:54', 21522045, 'Fakultas Teknologi Industri');
INSERT INTO "complaints" ("id", "ticket_number", "name", "email", "phone", "category", "subject", "message", "attachment_path", "is_anonymous", "status", "response", "responded_at", "ip_address", "created_at", "updated_at", "student_id", "faculty") VALUES (2, 'DPM-261029-3K9L', NULL, 'mahasiswa.fbe@students.uii.ac.id', NULL, 'Finansial & UKT', 'Transparansi Mekanisme Pengajuan Keringanan UKT Semester Genap', 'Kami mengharapkan adanya kejelasan batas waktu verifikasi berkas dan indikator penilaian bagi rekan-rekan mahasiswa yang mengajukan permohonan banding/keringanan pembayaran UKT.', NULL, TRUE, 'baru', NULL, NULL, NULL, '2026-10-30 07:58:53', '2026-10-30 12:58:56', 22311099, 'Fakultas Bisnis dan Ekonomika');
INSERT INTO "complaints" ("id", "ticket_number", "name", "email", "phone", "category", "subject", "message", "attachment_path", "is_anonymous", "status", "response", "responded_at", "ip_address", "created_at", "updated_at", "student_id", "faculty") VALUES (3, 'DPM-261028-9F2M', 'Nabila Zahra Syahrani', 'nabila.zahra@students.uii.ac.id', 085712349988, 'Advokasi & Kebijakan Kampus', 'Advokasi Perpanjangan Jam Operasional Perpustakaan Pusat UII', 'Sehubungan dengan meningkatnya kebutuhan ruang belajar yang representatif dan kondusif bagi mahasiswa menjelang periode ujian, kami mengusulkan advokasi perpanjangan jam operasional Perpustakaan Pusat hingga pukul 21.00 WIB.', NULL, FALSE, 'diproses', NULL, NULL, NULL, '2026-10-29 12:58:53', '2026-10-30 12:58:57', 23411012, 'Fakultas Hukum');
INSERT INTO "complaints" ("id", "ticket_number", "name", "email", "phone", "category", "subject", "message", "attachment_path", "is_anonymous", "status", "response", "responded_at", "ip_address", "created_at", "updated_at", "student_id", "faculty") VALUES (4, 'DPM-261025-1C4E', 'Muhammad Ilham Pratama', 'ilham.pratama@students.uii.ac.id', 087811223344, 'Konstitusi KM UII', 'Klarifikasi Tahapan Sosialisasi Perubahan PKM Pemilwa KM UII', 'Bagaimanakah alur keterlibatan lembaga legislatif fakultas dalam pembahasan draf akhir revisi PKM tentang Pemilwa sebelum disahkan dalam Sidang Paripurna DPM UII?', NULL, FALSE, 'selesai', 'Terima kasih atas perhatian dan aspirasi Saudara. Komisi I (Legislasi) DPM UII telah menyelenggarakan agenda Uji Publik Draf PKM Pemilwa bersama delegasi DPM Fakultas se-UII. Risalah pembahasan dan matriks persandingan pasal dapat diakses terbuka pada portal ini.', '2026-10-28 12:58:53', NULL, '2026-10-26 12:58:53', '2026-10-30 12:58:59', 20320078, 'Fakultas Ilmu Agama Islam');
INSERT INTO "complaints" ("id", "ticket_number", "name", "email", "phone", "category", "subject", "message", "attachment_path", "is_anonymous", "status", "response", "responded_at", "ip_address", "created_at", "updated_at", "student_id", "faculty") VALUES (5, 'DPM-261020-8H5Z', 'Rendi Kurniawan', 'rendi.k@students.uii.ac.id', 089988776655, 'Lainnya', 'Pengajuan Proposal Sponsor Produk Minuman Luar Kampus', 'Pengajuan proposal kerjasama sponsorship komersial untuk kegiatan perlombaan eksternal.', NULL, FALSE, 'ditolak', 'Kanal Layanan Aspirasi DPM UII dikhususkan untuk penyerapan aspirasi, advokasi kebijakan kemahasiswaan, dan pengawalan hak-hak mahasiswa KM UII. Untuk pengajuan sponsorship dan kerjasama komersial, silakan berkoordinasi langsung dengan Direktorat Kemitraan Kampus.', '2026-10-23 12:58:53', NULL, '2026-10-21 12:58:53', '2026-10-30 12:59:00', 22511033, 'Fakultas Teknik Sipil dan Perencanaan');
INSERT INTO "bio_links" ("id", "site_name", "tagline", "handle", "logo", "description", "theme_color", "social_links", "address", "email", "phone", "is_active", "created_at", "updated_at") VALUES (1, 'DPM UII', 'Dewan Permusyawaratan Mahasiswa UII', '@dpmuii', NULL, 'Portal resmi DPM UII — produk hukum, surat keputusan, laporan, dan aspirasi mahasiswa.', '#001E43', '[{"label":"Instagram","icon":"fa-brands fa-instagram","url":"https:\/\/www.instagram.com\/dpmuii\/"},{"label":"LinkedIn","icon":"fa-brands fa-linkedin-in","url":"https:\/\/www.linkedin.com\/company\/dewan-permusyawaratan-mahasiswa\/"}]', 'Kampus Terpadu UII, Jl. Kaliurang KM 14.5, Sleman, Yogyakarta', 'dpm@uii.ac.id', '0815 1109 2004', TRUE, '2026-10-30 12:59:02', '2026-10-30 12:59:02');
