INSERT INTO "settings" ("id", "key", "value", "created_at", "updated_at") VALUES (5, 'hero_subtitle', 'Lembaga legislatif tertinggi dalam sistem student government KM UII: menyusun produk hukum, mengawasi jalannya pemerintahan mahasiswa, dan menyalurkan aspirasi mahasiswa.', '2026-10-30 12:56:37', '2026-10-30 12:56:37');
