INSERT INTO "settings" ("id", "key", "value", "created_at", "updated_at") VALUES (7, 'about_text', 'Keluarga Mahasiswa Universitas Islam Indonesia (KM UII) berdiri pada 21 September 1950 dengan ciri khas “student government”: pemerintahan dari, oleh, dan untuk mahasiswa. DPM UII menjalankan fungsi legislasi, pengawasan, dan penganggaran dalam sistem tersebut.', '2026-10-30 12:56:41', '2026-10-30 12:56:41');
