INSERT INTO "settings" ("id", "key", "value", "created_at", "updated_at") VALUES (17, 'meta_description', 'Portal resmi DPM UII — produk hukum, surat keputusan, laporan keuangan triwulan, laporan kinerja, dan berita terbaru.', '2026-10-30 12:56:56', '2026-10-30 12:56:56');
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (1, 'DPM UII Gelar Sidang Paripurna Ke-1 Periode 2025/2026', 'dpm-uii-gelar-sidang-paripurna-ke-1-periode-2025-2026', 'Dewan Permusyawaratan Mahasiswa UII menyelenggarakan Sidang Paripurna pertama periode 2025/2026 untuk membahas program kerja dan anggaran tahunan.', '<p>Pada hari Senin, 15 September 2025, DPM UII menggelar Sidang Paripurna pertama periode 2025/2026 di Ruang Sidang DPM UII. Sidang dibuka oleh Ketua DPM UII dan dihadiri seluruh anggota dewan.</p><p>Agenda utama sidang meliputi pembahasan program kerja tahunan, anggaran pendapatan dan belanja (APB), serta penetapan struktur pengurus alat kelengkapan dewan.</p><p>"Sidang ini menjadi momen penting untuk menyepakati arah kebijakan dewan selama satu periode ke depan," ujar Ketua DPM UII.</p>', 'draft', '2026-10-28 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:09', '2026-10-30 16:44:09', 1);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (2, 'PKM UII No. 3 Tahun 2024 Resmi Berlaku: Tentang Distribusi Dana KM UII', 'pkm-uis-no-3-tahun-2024-resmi-berlaku-tentang-distribusi-dana-km-uis', 'Peraturan Keluarga Mahasiswa Nomor 3 Tahun 2024 mengenai pengelolaan dan distribusi dana KM UII telah disahkan dan berlaku efektif.', '<p>PKM UII Nomor 3 Tahun 2024 tentang Distribusi dan Alokasi Dana KM UII telah disahkan oleh Pimpinan DPM UII pada tanggal 10 Agustus 2024.</p><p>Peraturan ini mengatur mekanisme transparan dalam pengelolaan dana Kemahasiswaan, termasuk alokasi untuk Lembaga Eksekutif, Alat Kelengkapan Dewan, dan Lembaga Khusus.</p>', 'draft', '2026-10-25 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:12', '2026-10-30 16:44:12', 1);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (3, 'Rapat Koordinasi Alat Kelengkapan Dewan Periode 2025/2026', 'rapat-koordinasi-alat-kelengkapan-dewan-periode-2025-2026', 'Ketua DPM UII memimpin rapat koordinasi seluruh alat kelengkapan dewan untuk menyelaraskan program kerja periode 2025/2026.', '<p>Rapat koordinasi dihadiri oleh ketua-ketua Baleg, Bawas, BAK, BPA, Bksaj, dan Mentari. Setiap alat kelengkapan menyampaikan rencana program kerja masing-masing.</p>', 'draft', '2026-10-20 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:14', '2026-10-30 16:44:14', 2);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (4, 'Forum Aspirasi Mahasiswa Tingkat Fakultas - Gelombang I', 'forum-aspirasi-mahasiswa-tingkat-fakultas-gelombang-i', 'DPM UII melalui BKSAJ menggelar Forum Aspirasi Mahasiswa tingkat fakultas untuk menampung keluhan dan usulan mahasiswa.', '<p>Forum Aspirasi diadakan secara hybrid (online dan offline) di 8 fakultas di UII. Mahasiswa dapat menyampaikan aspirasi langsung ke wakil DPM Fakultas masing-masing.</p><p>Hasil forum akan dijadikan bahan pertimbangan dalam penyusunan program advokasi DPM UII.</p>', 'draft', '2026-10-15 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:16', '2026-10-30 16:44:16', 2);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (5, 'Pelatihan Legislasi untuk Anggota DPM UII Baru', 'pelatihan-legislasi-untuk-anggota-dpm-uis-baru', 'Badan Legislasi (Baleg) mengadakan pelatihan dasar legislasi bagi anggota DPM UII periode 2025/2026.', '<p>Pelatihan berlangsung selama 2 hari dan mencakup materi: tata cara sidang, teknis drafting peraturan, dan kajian hukum dasar.</p><p>"Kami ingin memastikan seluruh anggota memahami proses legislasi dengan baik," kata Ketua Baleg.</p>', 'draft', '2026-10-10 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:19', '2026-10-30 16:44:19', 2);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (6, 'Audit Keuangan Lembaga KM UII Triwulan II 2024', 'audit-keuangan-lembaga-km-uis-triwulan-ii-2024', 'Badan Audit Kemahasiswaan (BAK) menyelesaikan audit keuangan lembaga-lembaga KM UII untuk triwulan II tahun 2024.', '<p>Hasil audit menunjukkan bahwa mayoritas lembaga telah mengelola dana sesuai peraturan. Beberapa temuan perbaikan telah disampaikan ke masing-masing lembaga.</p>', 'draft', '2026-09-30 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:21', '2026-10-30 16:44:21', 1);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (7, 'Pembukaan Lomba Karya Tulis Ilmiah (LKTI) KM UII 2025', 'pembukaan-lomba-karya-tulis-ilmiah-lkti-km-uis-2025', 'Mentari DPM UII membuka pendaftaran Lomba Karya Tulis Ilmiah tingkat KM UII tahun 2025.', '<p>Lomba ini terbuka untuk seluruh mahasiswa UII dengan tema "Inovasi Mahasiswa untuk Kampus Berkelanjutan". Hadiah total mencapai 20 juta rupiah.</p><p>Pendaftaran dibuka hingga 31 Oktober 2025 melalui website resmi DPM UII.</p>', 'draft', '2026-09-20 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:23', '2026-10-30 16:44:23', 2);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (8, 'Kunjungan Kerja DPM UII ke DPM Se-Jawa Tengah', 'kunjungan-kerja-dpm-uis-ke-dpm-se-jawa-tengah', 'Delegasi DPM UII melakukan kunjungan kerja ke DPM Universitas lain di Jawa Tengah untuk silaturahmi dan sharing pengalaman.', '<p>Kunjungan dilakukan ke 4 universitas: UNDIP, UNNES, UNS, dan UGM. Bahasan meliputi penguatan legislasi mahasiswa, advokasi kebijakan, dan kerjasama antar DPM.</p>', 'draft', '2026-09-10 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:26', '2026-10-30 16:44:26', 2);
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "featured_image", "meta_title", "meta_description", "created_at", "updated_at", "post_category_id") VALUES (9, 'Pengumuman Penerima Beasiswa Prestasi KM UII 2024', 'pengumuman-penerima-beasiswa-prestasi-km-uis-2024', 'DPM UII melalui BPA mengumumkan daftar penerima beasiswa prestasi bagi mahasiswa berprestasi akademik dan non-akademik.', '<p>Sebanyak 25 mahasiswa menerima beasiswa prestasi tahun 2024. Seleksi dilakukan berdasarkan IPK, prestasi lomba, dan aktifitas organisasi.</p>', 'draft', '2026-08-31 16:44:08', NULL, NULL, NULL, '2026-10-30 16:44:28', '2026-10-30 16:44:28', 1);
