INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (2, NULL, 'lembaga', 'Mentari', 'mentari', 'Mentari adalah alat kelengkapan Dewan Permusyawaratan Mahasiswa UII yang bertanggung jawab atas media komunikasi, kesekretariatan, dokumentasi, dan penerbitan publikasi resmi DPM. Unit ini menjadi jembatan informasi antara dewan dengan mahasiswa dan publik.', NULL, 2, TRUE, '2026-10-30 12:58:13', '2026-10-30 13:14:02', 'Mentari', 'Mengelola media komunikasi DPM UII
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (3, NULL, 'badan', 'Badan Legislasi', 'badan-legislasi', 'Badan Legislasi (Baleg) berfungsi menyusun, mengkaji, dan mengkoordinasikan proses pembentukan produk hukum DPM UII. Termasuk rancangan peraturan, kajian hukum, serta pengarsipan dan dokumentasi produk hukum.', NULL, 3, TRUE, '2026-10-30 12:58:15', '2026-10-30 13:14:15', 'Baleg', 'Menyusun rancangan produk hukum DPM
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (4, NULL, 'badan', 'Badan Pengawasan', 'badan-pengawasan', 'Badan Pengawasan (Bawas) menjalankan fungsi pengawasan terhadap pelaksanaan fungsi dewan, pengelolaan dana dan aset, serta investigasi pelanggaran. Menyusun laporan pengawasan berkala untuk akuntabilitas dewan.', NULL, 4, TRUE, '2026-10-30 12:58:17', '2026-10-30 13:14:29', 'Bawas', 'Mengawasi pelaksanaan fungsi dewan
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (6, NULL, 'badan', 'Badan Audit Kemahasiswaan', 'badan-audit-kemahasiswaan', 'Badan Audit Kemahasiswaan (BAK) bertugas mengaudit keuangan seluruh lembaga KM UII, memeriksa kelayakan pengelolaan dana, menyusun Laporan Hasil Audit (LHA), dan memberikan rekomendasi perbaikan pengelolaan keuangan.', NULL, 6, TRUE, '2026-10-30 12:58:22', '2026-10-30 13:14:52', 'BAK', 'Mengaudit keuangan lembaga KM UII
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (7, NULL, 'badan', 'Badan Pengelola Aset', 'badan-pengelola-aset', 'Badan Pengelola Aset (BPA) mengelola inventaris aset DPM, mencatat dan memelihara aset, menyusun laporan pengelolaan aset, serta mengkoordinasikan pengadaan barang dan jasa untuk kebutuhan dewan.', NULL, 7, TRUE, '2026-10-30 12:58:24', '2026-10-30 13:15:04', 'BPA', 'Mengelola inventaris aset DPM
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (1, NULL, 'pimpinan', 'Pimpinan Dewan', 'pimpinan-dewan', 'Pimpinan Dewan memimpin rapat paripurna, mewakili dewan dalam forum eksternal, mengkoordinasikan kerja seluruh alat kelengkapan, serta menetapkan agenda kebijakan dewan untuk periode kepengurusan.', NULL, 1, TRUE, '2026-10-30 12:58:11', '2026-10-30 14:51:31', NULL, 'Memimpin rapat paripurna dewan
INSERT INTO "organizational_units" ("id", "parent_id", "type", "name", "slug", "description", "logo_path", "sort_order", "is_active", "created_at", "updated_at", "abbreviation", "tasks", "work_programs", "email") VALUES (5, NULL, 'badan', 'Badan Kerjasama, Advokasi, dan Jaringan', 'badan-kerjasama-advokasi-dan-jaringan', 'Deskripsi Badan Kerjasama, Advokasi, dan Jaringan akan diisi.', NULL, 5, TRUE, '2026-10-30 12:58:20', '2026-10-30 14:51:38', 'Bksaj', 'Tugas dan fungsi Badan Kerjasama, Advokasi, dan Jaringan akan diisi.', 'Program kerja Badan Kerjasama, Advokasi, dan Jaringan akan diisi.', 'badan-kerjasama-advokasi-dan-jaringan@dpm.uii.ac.id');
